//! Input-state ABI shared with non-Rust feeders.
//!
//! The active format is the self-delimiting tagged-group frame in
//! [`v6`]: the browser writes it into WASM linear memory each frame, a
//! native shell hands the same bytes across an FFI boundary, and the
//! same frame could arrive over a serial link to an embedded panel. The
//! JS writer in `clients/web/state-abi.js` and the Rust codec are pinned
//! against the same committed golden frames in
//! `crates/pilotage-instrument-state/fixtures/`
//! (regenerated by `cargo xtask gen-state-fixture`), so the two sides of
//! the boundary can only drift by turning CI red.

pub mod v6;

/// NaN-as-absent decoding for optional wire floats.
pub(crate) fn opt(v: f32) -> Option<f32> {
    if v.is_nan() { None } else { Some(v) }
}

/// NaN-as-absent encoding for optional wire floats.
pub(crate) fn or_nan(v: Option<f32>) -> f32 {
    v.unwrap_or(f32::NAN)
}
